import{_t as e,it as t,n,rt as r}from"./chunks/framework.C6TizvAB.js";var i=JSON.parse(`{"title":"Gemma4-12B本地部署","description":"Gemma4-12B 依托于强大的 120 亿参数模型，它在本地环境中即可流畅运行。处理敏感隐私文档、进行长篇逻辑推理，还能作为你的全天候创作伙伴","frontmatter":{"title":"Gemma4-12B本地部署","description":"Gemma4-12B 依托于强大的 120 亿参数模型，它在本地环境中即可流畅运行。处理敏感隐私文档、进行长篇逻辑推理，还能作为你的全天候创作伙伴","date":"2026-06-07T00:00:00.000Z","category":"AI世界","tags":["AI技术"],"order":4},"headers":[],"relativePath":"articles/ai/ai-tech/gemma4-12b.md","filePath":"articles/ai/ai-tech/gemma4-12b.md","articleMeta":{"updated":"2026-06-07","words":1145,"minutes":3}}`),a={name:`articles/ai/ai-tech/gemma4-12b.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="gemma4-12b本地部署-0token的个人助理" tabindex="-1">Gemma4-12B本地部署，0token的个人助理 <a class="header-anchor" href="#gemma4-12b本地部署-0token的个人助理" aria-label="Permalink to “Gemma4-12B本地部署，0token的个人助理”">​</a></h1><h2 id="安装gemma4-12b" tabindex="-1">安装Gemma4-12B <a class="header-anchor" href="#安装gemma4-12b" aria-label="Permalink to “安装Gemma4-12B”">​</a></h2><blockquote><p>Gemma4-12B发布于2026年6月，参数量120亿，只需 <strong>16GB VRAM（显存）或苹果 Mac 的统一内存</strong>即可流畅运行。</p><p>Gemma 4 12B 支持高达 <strong>256K 的上下文窗口</strong>（Context Window）。在本地运行时，你可以直接把一整本书、长篇研报或是数十个代码文件一次性“喂”给它，而它能保持极高的信息召回率。</p></blockquote><h3 id="_1-下载lm-studio" tabindex="-1">1. 下载LM-studio <a class="header-anchor" href="#_1-下载lm-studio" aria-label="Permalink to “1. 下载LM-studio”">​</a></h3><p>访问 <a href="https://lmstudio.ai/%5D" target="_blank" rel="noreferrer">https://lmstudio.ai/</a> 下载，</p><p><strong>LM Studio</strong> 是一款非常强大且易于使用的<strong>本地大语言模型（LLM）运行工具</strong>。它允许用户在自己的电脑上（完全离线）下载、安装和运行各种开源大模型。</p><h3 id="_2-本地部署gemma4-12b" tabindex="-1">2. 本地部署Gemma4-12B <a class="header-anchor" href="#_2-本地部署gemma4-12b" aria-label="Permalink to “2. 本地部署Gemma4-12B”">​</a></h3><p>在LM-studio中一键安装Gemma4-12B，小白傻瓜式。安装好后就可以使用了。</p><p><img src="https://static.wyclab.com/image-20260607212315331260607.png" alt="image-20260607212315331"></p><h3 id="_3-内存占用实测" tabindex="-1">3. 内存占用实测 <a class="header-anchor" href="#_3-内存占用实测" aria-label="Permalink to “3. 内存占用实测”">​</a></h3><p>实测MacBook Air M5 16GB，上下文开不到256K，只能开到25K左右，内存占用大约10GB左右。对话时GPU占用是100%。</p><p><img src="https://static.wyclab.com/image-20260607212859660260607.png" alt="image-20260607212859660"></p><h2 id="开始使用" tabindex="-1">开始使用 <a class="header-anchor" href="#开始使用" aria-label="Permalink to “开始使用”">​</a></h2><p>本地部署后，可以作为可离线使用的、本地运行的AI助理，智商在线，不怕隐私泄漏，可以在本地处理基本的任务。</p><h3 id="_1-翻译助理" tabindex="-1">1. 翻译助理 <a class="header-anchor" href="#_1-翻译助理" aria-label="Permalink to “1. 翻译助理”">​</a></h3><p>提示词：翻译成中文</p><p><img src="https://static.wyclab.com/image-20260607211012423260607.png" alt="image-20260607211012423"></p><h3 id="_2-ocr助理" tabindex="-1">2. ocr助理 <a class="header-anchor" href="#_2-ocr助理" aria-label="Permalink to “2. ocr助理”">​</a></h3><p>提示词：ocr</p><p><img src="https://static.wyclab.com/image-20260607210855843260607.png" alt="image-20260607210855843"></p><h3 id="_3-制表助理" tabindex="-1">3. 制表助理 <a class="header-anchor" href="#_3-制表助理" aria-label="Permalink to “3. 制表助理”">​</a></h3><p>提示词：将上述内容做成表格</p><p><img src="https://static.wyclab.com/image-20260607210929545260607.png" alt="image-20260607210929545"></p><h3 id="_4-写作-code助理" tabindex="-1">4. 写作/code助理 <a class="header-anchor" href="#_4-写作-code助理" aria-label="Permalink to “4. 写作/code助理”">​</a></h3><p><img src="https://static.wyclab.com/image-20260607213229913260607.png" alt="image-20260607213229913"></p>`,25)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};